topics.code_example:
SELECT nombre, calificacion
FROM estudiantes
WHERE calificacion >= 14 AND activo = 1;

SELECT nombre, calificacion, fecha_entrega
FROM entregas
ORDER BY calificacion DESC, fecha_entrega ASC;

SELECT e.nombre, t.titulo_tarea, t.calificacion
FROM estudiantes e
LEFT JOIN tareas t ON e.id_estudiante = t.id_estudiante;

SELECT id_curso, COUNT(*) AS total_inscritos, COUNT(DISTINCT id_estudiante) AS estudiantes_unicos
FROM matriculas
GROUP BY id_curso;
